const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w08.mjs').href);
const r = $json; if (!r.id) return { json: { action: 'none' } };
const lead = { id: r.id, first_name: r.first_name, language: r.language, origin: r.origin, stage: r.stage, conv_state: r.conv_state || {}, opted_out_at: r.opted_out_at, first_message_at: r.first_message_at, broker_id: r.broker_id };
const ctx = { has_live_booking: r.has_live_booking, suppressed: r.suppressed, sent: new Set(r.sent || []), last_inbound_ms: r.last_inbound_at ? Date.parse(r.last_inbound_at) : NaN, outbound_count: Number(r.outbound_count || 0), broker: { contact_person: r.contact_person, bio_short: r.bio_short, intro_video_url: r.intro_video_url } };
const d = L.due(lead, ctx, Date.now());
return { json: { ...d, lead_id: r.id, brand_id: r.brand_id, broker_id: r.broker_id, phone: r.phone, lang: r.language === 'af' ? 'af' : 'en' } };

const d = $('Decide (w08.due)').item.json;
const btn = d.buttons.map(([id, t]) => [id + d.payload_suffix, t]);
let wa;
if (d.channel === 'template') {
  const comps = [];
  if (d.header && d.header.type === 'video') comps.push({ type: 'header', parameters: [{ type: 'video', video: { link: d.header.link } }] });
  if (d.header && d.header.type === 'text') comps.push({ type: 'header', parameters: d.header.params.map((t) => ({ type: 'text', text: t })) });
  comps.push({ type: 'body', parameters: d.vars.map((t) => ({ type: 'text', text: String(t) })) });
  btn.forEach(([p], i) => comps.push({ type: 'button', sub_type: 'quick_reply', index: String(i), parameters: [{ type: 'payload', payload: p }] }));
  wa = { messaging_product: 'whatsapp', to: d.phone, type: 'template', template: { name: d.template, language: { code: 'en' }, components: comps } };
} else {
  // inside the 24-h window: same approved words as a session interactive message (no template fee)
  const words = { unbooked_nudge_2h: 'Hi ' + d.vars[0] + ', following up on your life cover enquiry. A call with ' + d.vars[1] + ' takes about 30 minutes, and there is nothing to buy on the call. Tap below to see open times.', unbooked_nudge_24h: 'Hi ' + d.vars[0] + ', here is ' + d.vars[1] + ' in about 25 seconds, so you know who you would be speaking to about your enquiry. Tap below to see open times.', unbooked_nudge_24h_text: 'Hi ' + d.vars[0] + ', a little about the adviser for your enquiry: ' + d.vars[1] + ' Tap below to see open times.', unbooked_nudge_72h: 'Hi ' + d.vars[0] + ', this is our last message about your life cover enquiry. If you would still like a 30-minute call with ' + d.vars[1] + ', tap below to pick a time. If not, no problem, we will not message again.' }[d.template];
  const header = d.header && d.header.type === 'video' ? { type: 'video', video: { link: d.header.link } } : undefined;
  wa = { messaging_product: 'whatsapp', to: d.phone, type: 'interactive', interactive: { type: 'button', ...(header ? { header } : {}), body: { text: words + ' Reply STOP to opt out.' }, action: { buttons: btn.map(([id, t]) => ({ type: 'reply', reply: { id, title: t } })) } } };
}
return { json: { ...d, wa } };

