const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w08.mjs').href);
const j = $json; const p = (j.msg && j.msg.payload) || (j.delegate && j.delegate.action === 'close' ? 'no_thanks' : '');
const r = L.onTap(j.lead || {}, p);
if (!r) return { json: { skip: true } };
return { json: { skip: false, lead: j.lead, brand_id: j.lead.brand_id, msg: j.msg, r, from: j.msg && j.msg.from } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const { LINES } = await import(url.pathToFileURL(REPO + '/conversation/lines.mjs').href);
const j = $('On tap (w08.onTap)').item.json;
const lang = j.lead.language === 'af' ? 'af' : 'en';
return { json: { ...j, wa: { messaging_product: 'whatsapp', to: j.from, type: 'text', text: { body: LINES[lang].CLOSE_UNBOOKED } } } };
